# Define the 3x3 board coordinates
coords = [(r, c) for r in range(1, 4) for c in range(1, 4)]

# G targets all 9 squares
G_targets = coords

# L targets the 4 squares adjacent to the center (Edge Middles)
L_targets = [(1, 2), (2, 1), (2, 3), (3, 2)]

# Function to check if a target point (i, j) is covered by a growth centered at (r, c)
def is_covered(i, j, r, c):
    return abs(i - r) <= 1 and abs(j - c) <= 1

# Calculate G_total contribution for every square (i, j)
g_counts = {coord: 0 for coord in coords}
for i, j in coords:
    for r_target, c_target in G_targets:
        if is_covered(i, j, r_target, c_target):
            g_counts[(i, j)] += 1

# Calculate L_total reduction for every square (i, j)
l_counts = {coord: 0 for coord in coords}
for coord in L_targets:
    l_counts[coord] += 1

# Determine the net increase for the 5 remaining squares (Center + Corners)
R_squares = [(2, 2), (1, 1), (1, 3), (3, 1), (3, 3)]
net_increases = {}

print("--- Detailed Coverage ---")
for coord in coords:
    print(f"Square {coord}: G_count={g_counts[coord]}, L_count={l_counts[coord]}")

print("\n--- Net Increase for Remaining 5 Squares (R) ---")
for r_sq in R_squares:
    net_h = g_counts[r_sq] - l_counts[r_sq]
    net_increases[r_sq] = net_h
    print(f"Square {r_sq}: Net Increase = {net_h}")
